/* The Bluetooth golden vectors were generated by the original Python daemon's
 * build_descriptors() (int_maxp=16) and build_strings(), so the generic builder is pinned
 * byte-for-byte to what is known to work on the Pi. */
#include "check.h"
#include "ffs.h"
#include "hci.h"
#include "wlan.h"

static const char GOLDEN_BT_DESCS[] =
    "03000000500000004300000004000000040000000904000003e00101010705810310000107058202"
    "400000070503024000000904000003e0010101070581031000040705820200020007050302000200";
static const char GOLDEN_BT_STRS[] = "020000001c0000000100000001000000090450692042542048434900";

static void to_hex(const uint8_t *p, size_t n, char *out)
{
    for (size_t i = 0; i < n; i++)
        sprintf(out + 2 * i, "%02x", p[i]);
}

int main(void)
{
    uint8_t buf[512];
    char hex[2 * sizeof buf + 1];
    struct ffs_fn_spec bt;
    hci_fill_spec(&bt, 16);
    struct ffs_fn_spec bt_audio;
    hci_fill_sco_spec(&bt_audio);                      /* the audio function: checked structurally below */
    bt.n_extra = 0;                                    /* the byte-exact golden is for the control interface alone */

    size_t n = ffs_build_descriptors(&bt, buf, sizeof buf);
    CHECK(n == 80, "BT descriptor length %zu, want 80", n);
    to_hex(buf, n, hex);
    CHECK(strcmp(hex, GOLDEN_BT_DESCS) == 0, "BT descriptors differ:\n got  %s\n want %s", hex, GOLDEN_BT_DESCS);

    n = ffs_build_strings(bt.name, buf, sizeof buf);
    CHECK(n == 28, "BT strings length %zu, want 28", n);
    to_hex(buf, n, hex);
    CHECK(strcmp(hex, GOLDEN_BT_STRS) == 0, "BT strings differ:\n got  %s\n want %s", hex, GOLDEN_BT_STRS);

    /* Overflow is reported, not silently truncated. */
    CHECK(ffs_build_descriptors(&bt, buf, 79) == 0, "79-byte buffer should fail");
    CHECK(ffs_build_descriptors(&bt, buf, 80) == 80, "80-byte buffer should fit exactly");
    CHECK(ffs_build_strings(bt.name, buf, 27) == 0, "27-byte strings buffer should fail");

    /* The audio function: its one interface (number 0) with alternate settings 0 (none), 1 and 2, each alternate setting with
     * its own two isochronous endpoints (FunctionFS rejects one endpoint in two settings). */
    {
        n = ffs_build_descriptors(&bt_audio, buf, sizeof buf);
        CHECK(n > 0, "audio descriptors fit");
        uint32_t cnt;
        memcpy(&cnt, buf + 12, 4);
        CHECK(cnt == (1) + (1 + 2) + (1 + 2), "descriptor count %u", cnt);
        int ifaces = 0, eps = 0, isoc = 0, alts[8] = { 0 };
        for (size_t o = 20; o + 2 <= n && o < 20 + 3 * 9 + 4 * 7; ) {          /* the full-speed list */
            if (buf[o + 1] == 4) { alts[ifaces++] = (buf[o + 2] << 4) | buf[o + 3]; }
            if (buf[o + 1] == 5) { eps++; if ((buf[o + 3] & 3) == 1) isoc++; }
            o += buf[o];
        }
        CHECK(ifaces == 3 && eps == 4 && isoc == 4, "ifaces=%d eps=%d isoc=%d", ifaces, eps, isoc);
        CHECK(alts[0] == 0x00 && alts[1] == 0x01 && alts[2] == 0x02, "interface/alt numbering");
        CHECK(buf[20 + 4] == 0, "alternate setting 0 has no endpoints");
    }

    /* The WiFi function: interface class FF/02/FF, two bulk endpoints, and crucially it must NOT
     * claim device-recipient control requests (the Bluetooth function owns those). */
    struct ffs_fn_spec wl;
    wlan_fill_spec(&wl);
    n = ffs_build_descriptors(&wl, buf, sizeof buf);
    CHECK(n == 12 + 8 + 2 * (9 + 2 * 7), "WiFi descriptor length %zu", n);
    uint32_t flags;
    memcpy(&flags, buf + 8, 4);
    CHECK((flags & FUNCTIONFS_ALL_CTRL_RECIP) == 0, "WiFi function must not set ALL_CTRL_RECIP");
    CHECK((flags & (FUNCTIONFS_HAS_FS_DESC | FUNCTIONFS_HAS_HS_DESC)) == 3, "FS+HS descriptors expected");
    /* first interface descriptor starts after head(12) + two counts(8) */
    CHECK(buf[20 + 5] == 0xFF && buf[20 + 6] == 0x02 && buf[20 + 7] == 0xFF, "interface class triple");
    CHECK(buf[20 + 4] == 2, "two endpoints");

    TEST_DONE("ffs");
}
